// Construct the edge based on edge_index
const auto& p0 = v0->point();
const auto& p1 = v1->point();
const auto& p2 = v2->point();

// Check which edge we're examining
if (edge_index == 0) {
    return triangulation.is_constrained(p0, p1);
} else if (edge_index == 1) {
    return triangulation.is_constrained(p1, p2);
} else if (edge_index == 2) {
    return triangulation.is_constrained(p2, p0);
}
return false;  // Invalid edge index
```

